"""Chapter 5 data: displays, local symbol rows and glossary (pure data, no rendering)."""
import re

_SUB = re.compile(r'(?<![\w$\\])([A-Za-z\u0370-\u03ff])_([A-Za-z0-9]+)(?![\w])')


def tx(text):
    """Turn plain `X_y` symbol mentions in prose into inline math."""
    return _SUB.sub(lambda m: '$' + m[1] + '_{' + m[2] + '}$', text)



def v(symbol, en, zh, unit, role_en, role_zh):
    return (symbol, tx(en), tx(zh), unit, tx(role_en), tx(role_zh))


